  'Drink Bracelets': 'Pulseiras de Bebida',
  '1 coloured ribbon or string per guest': '1 fita ou fio colorido por convidado',
  'Each guest ties a ribbon around their wrist at the start of the night.':
    'Cada convidado ata uma fita à volta do pulso no início da noite.',
