  'Agree on a limit and make sure there is water between drinks.':
    'Combinar um limite e garantir água entre bebidas.',
  'Ribbons in the wedding colours look good in the photos.':
    'Fitas com as cores do casamento ficam bem nas fotografias.',
  'Memory Book': 'Livro de Memórias',
  'Prepared beforehand; given at the party': 'Preparado antes; entregue na festa',
  'A big album or notebook': 'Álbum ou caderno grande',
  Photos: 'Fotografias',
  'Pens, stickers and glue': 'Canetas, autocolantes e cola',
  'Well in advance, the organiser collects a page from each guest, with photos, memories and funny stories with the bride.':
    'O organizador recolhe com antecedência uma página de cada convidado, com fotografias, recordações e histórias engraçadas com a noiva.',
